from decimal import Decimal, ROUND_HALF_UP


class Money:
    def __init__(self, amount):
        if isinstance(amount, Money):
            self._cents = amount._cents
        elif isinstance(amount, int):
            self._cents = amount * 100
        elif isinstance(amount, Decimal):
            self._cents = int((amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100).to_integral_value())
        elif isinstance(amount, float):
            self._cents = int((Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100).to_integral_value())
        else:
            self._cents = int((Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100).to_integral_value())

    @classmethod
    def from_cents(cls, cents):
        return cls._from_cents(cents)

    @classmethod
    def _from_cents(cls, cents):
        money = cls.__new__(cls)
        money._cents = int(cents)
        return money

    @property
    def amount(self):
        return Decimal(self._cents) / Decimal(100)

    def __add__(self, other):
        if not isinstance(other, Money):
            other = Money(other)
        return Money._from_cents(self._cents + other._cents)

    def __sub__(self, other):
        if not isinstance(other, Money):
            other = Money(other)
        return Money._from_cents(self._cents - other._cents)

    def __mul__(self, qty):
        if isinstance(qty, int):
            return Money._from_cents(self._cents * qty)

        if isinstance(qty, Decimal):
            qty_dec = qty
        elif isinstance(qty, float):
            qty_dec = Decimal(str(qty))
        else:
            qty_dec = Decimal(str(qty))

        product_cents = (Decimal(self._cents) * qty_dec).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        return Money._from_cents(int(product_cents))

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents == other._cents

    def __repr__(self):
        sign = "-" if self._cents < 0 else ""
        abs_cents = abs(self._cents)
        dollars, cents = divmod(abs_cents, 100)
        return f"Money({sign}{dollars}.{cents:02d})"

    def cents(self):
        return self._cents

