import os
import re
from urllib.parse import unquote

_WINDOWS_ABS_RE = re.compile(r"^[A-Za-z]:[\\/]")


def safe_join(base, user_path):
    if not isinstance(user_path, str):
        raise ValueError("user_path must be a string")

    decoded = unquote(user_path)

    if "\x00" in decoded:
        raise ValueError("NUL byte in path")

    normalized = decoded.replace("\\", "/")

    if normalized.startswith("/") or _WINDOWS_ABS_RE.match(normalized):
        raise ValueError("absolute path not allowed")

    base_real = os.path.realpath(os.path.abspath(base))
    candidate = os.path.realpath(os.path.join(base_real, normalized))

    if candidate == base_real:
        return candidate

    try:
        common = os.path.commonpath([base_real, candidate])
    except ValueError:
        raise ValueError("path escapes base")

    if common != base_real:
        raise ValueError("path escapes base")

    return candidate

