def migrate(conn):
    schema_rows = conn.execute("SELECT rowid, version FROM schema_version").fetchall()
    current_version = schema_rows[0][1] if schema_rows else None

    if current_version == 2:
        if len(schema_rows) > 1:
            keep_rowid = schema_rows[0][0]
            conn.execute("UPDATE schema_version SET version = 2 WHERE rowid = ?", (keep_rowid,))
            conn.execute("DELETE FROM schema_version WHERE rowid != ?", (keep_rowid,))
            conn.commit()
        return

    columns = [row[1] for row in conn.execute("PRAGMA table_info(users)")]
    if "email_domain" not in columns:
        conn.execute("ALTER TABLE users ADD COLUMN email_domain TEXT")

    for user_id, email in conn.execute("SELECT id, email FROM users"):
        if email is None or "@" not in email:
            domain = None
        else:
            domain = email.rsplit("@", 1)[1].lower()
        conn.execute("UPDATE users SET email_domain = ? WHERE id = ?", (domain, user_id))

    if schema_rows:
        keep_rowid = schema_rows[0][0]
        conn.execute("UPDATE schema_version SET version = 2 WHERE rowid = ?", (keep_rowid,))
        conn.execute("DELETE FROM schema_version WHERE rowid != ?", (keep_rowid,))
    else:
        conn.execute("INSERT INTO schema_version (version) VALUES (2)")

    conn.commit()

