from decimal import Decimal, ROUND_HALF_UP


class Money:
    def __init__(self, amount):
        if isinstance(amount, Money):
            self._cents = amount._cents
            return

        if isinstance(amount, Decimal):
            value = amount
        elif isinstance(amount, float):
            value = Decimal(str(amount))
        else:
            value = Decimal(str(amount))

        self._cents = int(
            (value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100)
        )

    @classmethod
    def _from_cents(cls, cents):
        obj = cls.__new__(cls)
        obj._cents = int(cents)
        return obj

    @property
    def amount(self):
        return Decimal(self._cents) / Decimal(100)

    def cents(self):
        return self._cents

    def __add__(self, other):
        if not isinstance(other, Money):
            other = Money(other)
        return Money._from_cents(self._cents + other._cents)

    def __radd__(self, other):
        if other == 0:
            return self
        return Money(other) + self

    def __sub__(self, other):
        if not isinstance(other, Money):
            other = Money(other)
        return Money._from_cents(self._cents - other._cents)

    def __mul__(self, qty):
        if isinstance(qty, int):
            return Money._from_cents(self._cents * qty)

        if isinstance(qty, Decimal):
            factor = qty
        else:
            factor = Decimal(str(qty))

        return Money._from_cents(
            int((Decimal(self._cents) * factor).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        )

    def __rmul__(self, qty):
        return self.__mul__(qty)

    def __eq__(self, other):
        if isinstance(other, Money):
            return self._cents == other._cents

        try:
            return self._cents == Money(other)._cents
        except Exception:
            return NotImplemented

    def __hash__(self):
        return hash(self._cents)

    def __repr__(self):
        sign = "-" if self._cents < 0 else ""
        abs_cents = abs(self._cents)
        dollars, cents = divmod(abs_cents, 100)
        return f"Money({sign}{dollars}.{cents:02d})"

