import os
import re
from urllib.parse import unquote


def _is_within(base, path):
    try:
        return os.path.commonpath([base, path]) == base
    except ValueError:
        return False


def safe_join(base, user_path):
    if user_path is None:
        raise ValueError("user_path must not be None")

    if isinstance(user_path, bytes):
        decoded = unquote(user_path).decode("utf-8", "surrogateescape")
    elif isinstance(user_path, str):
        decoded = unquote(user_path)
    else:
        raise ValueError("user_path must be a string")

    if "\0" in decoded:
        raise ValueError("user_path must not contain NUL bytes")

    if decoded.startswith("/") or decoded.startswith("\\"):
        raise ValueError("user_path must not be an absolute path")

    if re.match(r"^[A-Za-z]:[\\/]", decoded):
        raise ValueError("user_path must not be an absolute path")

    normalized = decoded.replace("\\", "/")

    if normalized.startswith("/"):
        raise ValueError("user_path must not be an absolute path")

    try:
        base_abs = os.path.realpath(base)
        candidate = os.path.realpath(os.path.join(base_abs, normalized))
    except (OSError, ValueError):
        raise ValueError("unsafe or invalid path")

    if not _is_within(base_abs, candidate):
        raise ValueError("user_path resolves outside base")

    return candidate

