    def __init__(self, rate, capacity, clock):
        self.rate = rate
        self.capacity = capacity
        self.clock = clock
        self.tokens = capacity
        self.last = clock()

    def allow(self, cost=1):
        now = self.clock()
        if now > self.last:
            self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)
            self.last = now
        elif now < self.last:
            self.last = now

        if cost <= 0:
            return cost == 0
        if cost > self.capacity:
            return False

        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

