import sqlite3


def init_v1(conn):
    conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT)")
    conn.execute("CREATE TABLE schema_version (version INTEGER)")
    conn.execute("INSERT INTO schema_version VALUES (1)")
    conn.commit()


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def _ensure_single_schema_version(conn, new_version):
    try:
        count = conn.execute("SELECT COUNT(*) FROM schema_version").fetchone()[0]
    except sqlite3.OperationalError:
        conn.execute("CREATE TABLE schema_version (version INTEGER)")
        conn.execute("INSERT INTO schema_version (version) VALUES (?)", (new_version,))
        return

    if count == 0:
        conn.execute("INSERT INTO schema_version (version) VALUES (?)", (new_version,))
    elif count == 1:
        conn.execute("UPDATE schema_version SET version = ?", (new_version,))
    else:
        conn.execute(
            "UPDATE schema_version SET version = ? WHERE rowid = (SELECT MIN(rowid) FROM schema_version)",
            (new_version,),
        )
        conn.execute(
            "DELETE FROM schema_version WHERE rowid != (SELECT MIN(rowid) FROM schema_version)"
        )


def _email_domain(email):
    if email is None:
        return None

    if isinstance(email, bytes):
        email = email.decode("utf-8", "replace")
    else:
        email = str(email)

    at_index = email.rfind("@")
    if at_index == -1:
        return None

    return email[at_index + 1:].lower()


def migrate(conn):
    try:
        row = conn.execute("SELECT version FROM schema_version LIMIT 1").fetchone()
    except sqlite3.OperationalError:
        row = None

    current_version = row[0] if row else None

    if current_version == 2:
        _ensure_single_schema_version(conn, 2)
        conn.commit()
        return

    try:
        columns = [r[1] for r in conn.execute("PRAGMA table_info(users)")]
    except sqlite3.OperationalError:
        columns = []

    if "email_domain" not in columns:
        try:
            conn.execute("ALTER TABLE users ADD COLUMN email_domain TEXT")
        except sqlite3.OperationalError:
            conn.execute(
                "CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT, email_domain TEXT)"
            )

    rows = conn.execute("SELECT id, email FROM users WHERE email_domain IS NULL").fetchall()
    updates = [( _email_domain(email), user_id) for user_id, email in rows]

    if updates:
        conn.executemany("UPDATE users SET email_domain = ? WHERE id = ?", updates)

    _ensure_single_schema_version(conn, 2)
    conn.commit()

